;(()=>{const updates={"es":{"vulnerable":{"definition":"Que puede ser herido, perjudicado o afectado con facilidad por una amenaza o situación adversa; se aplica a personas, grupos, sistemas y otros elementos.","synonyms":["expuesto a daño","susceptible","en situación de riesgo"],"example":{"word":"vulnerable","text":"La nueva barrera protege a la población vulnerable frente a las inundaciones."},"exampleSynonym":{"word":"expuesta a daño","text":"La nueva barrera protege a la población expuesta a daños por las inundaciones."}},"flexible":{"definition":"Que puede doblarse sin romperse; también, que puede adaptarse o modificarse con facilidad, como un horario, una norma o una persona.","synonyms":["adaptable","maleable","ajustable"],"example":{"word":"flexible","text":"Acordaron un horario flexible que se adapta a las necesidades del equipo."},"exampleSynonym":{"word":"adaptable","text":"Acordaron un horario adaptable a las necesidades del equipo."}},"gradual":{"definition":"Que sucede o cambia poco a poco, en etapas sucesivas y no de manera repentina.","synonyms":["progresivo","paulatino","escalonado"],"example":{"word":"gradual","text":"El plan prevé un aumento gradual de las horas de atención."},"exampleSynonym":{"word":"paulatino","text":"El plan prevé un aumento paulatino de las horas de atención."}},"habitual":{"definition":"Que ocurre, se hace o se usa con frecuencia o de manera acostumbrada; también, propio o característico de una persona o situación.","synonyms":["frecuente","acostumbrado","usual"],"example":{"word":"habitual","text":"El médico preguntó por sus hábitos habituales de sueño."},"exampleSynonym":{"word":"acostumbrados","text":"El médico preguntó por sus hábitos acostumbrados de sueño."}},"impecable":{"definition":"Que no presenta defectos ni errores; también, irreprochable en su comportamiento, presentación o ejecución.","synonyms":["intachable","perfecto","irreprochable"],"example":{"word":"impecable","text":"La técnica realizó un trabajo impecable."},"exampleSynonym":{"word":"intachable","text":"La técnica realizó un trabajo intachable."}},"moderado":{"definition":"Que se mantiene dentro de límites razonables o de intensidad media, sin exceso; también, que actúa con mesura.","synonyms":["mesurado","de intensidad media","templado"],"example":{"word":"moderado","text":"El médico recomendó ejercicio moderado varias veces por semana."},"exampleSynonym":{"word":"de intensidad media","text":"El médico recomendó ejercicio de intensidad media varias veces por semana."}},"previsible":{"definition":"Que puede anticiparse o esperarse razonablemente a partir de la información disponible.","synonyms":["esperable","anticipable","predecible"],"example":{"word":"previsible","text":"El retraso era previsible por el cierre de la carretera."},"exampleSynonym":{"word":"esperable","text":"El retraso era esperable por el cierre de la carretera."}},"provisional":{"definition":"Que se establece o utiliza temporalmente, hasta que se adopte una solución o decisión definitiva.","synonyms":["temporal","transitorio","no definitivo"],"example":{"word":"provisional","text":"Recibió un permiso provisional mientras se tramitaba el definitivo."},"exampleSynonym":{"word":"temporal","text":"Recibió un permiso temporal mientras se tramitaba el definitivo."}},"viable":{"definition":"Que puede llevarse a cabo o funcionar en las condiciones existentes; en biología, capaz de desarrollarse o vivir.","synonyms":["factible","realizable","posible"],"example":{"word":"viable","text":"El equipo evaluó si la propuesta era viable con los recursos disponibles."},"exampleSynonym":{"word":"factible","text":"El equipo evaluó si la propuesta era factible con los recursos disponibles."}}}};for(const [id,fields] of Object.entries(updates.es)){const row=window.DICCIONARIOS.es.find(x=>x.id===id);if(row)Object.assign(row,fields);}})();

