;(()=>{const rows=window.DICCIONARIOS.es;const updates={"abogar":{"definition":"Defender o favorecer a alguien o algo, especialmente en un juicio o ante una autoridad; también, interceder en favor de una causa.","synonyms":["defender","interceder","representar"],"example":{"word":"abogar","text":"La abogada decidió abogar por su cliente ante el juez."},"exampleSynonym":{"word":"defender","text":"La abogada decidió defender a su cliente ante el juez."},"translation":{"en":"to advocate for; to plead for; to defend"}},"abohetado":{"definition":"(Dicho de una persona, animal o parte del cuerpo.) Hinchado, abuhado.","synonyms":["abuhado","hinchado","abotagado"],"example":{"word":"abohetado","text":"Tras la larga caminata, tenía los párpados abohetados."},"exampleSynonym":{"word":"abuhado","text":"Tras la larga caminata, tenía los párpados abuhados."},"translation":{"en":"swollen; puffy"}},"abolengo":{"definition":"Ascendencia de abuelos o antepasados; también, linaje ilustre, lugar de origen o larga tradición. Como adjetivo desusado, propio de los antepasados, antiguo o tradicional.","synonyms":["ascendencia","linaje","estirpe","prosapia","tradición"],"example":{"word":"abolengo","text":"La familia presume de un abolengo ligado a la historia del pueblo."},"exampleSynonym":{"word":"linaje","text":"La familia presume de un linaje ligado a la historia del pueblo."},"translation":{"en":"ancestry; lineage; origin; long-standing tradition"}},"abolicionismo":{"definition":"Movimiento que propugna la abolición de ciertas leyes o prácticas, como la esclavitud, la pena de muerte o la segregación racial.","synonyms":["movimiento abolicionista","doctrina abolicionista"],"example":{"word":"abolicionismo","text":"El abolicionismo impulsó la lucha contra la esclavitud."},"exampleSynonym":{"word":"movimiento abolicionista","text":"El movimiento abolicionista impulsó la lucha contra la esclavitud."},"translation":{"en":"abolitionism; abolitionist movement"}},"abollar":{"definition":"Producir una depresión en una superficie mediante un golpe o presión; también, adornar metales o telas con relieves semiesféricos. En Burgos, se usa además con el sentido de hollar.","synonyms":["abollanar","deformar","hundir","repujar"],"example":{"word":"abollar","text":"El golpe llegó a abollar la puerta del coche."},"exampleSynonym":{"word":"deformar","text":"El golpe llegó a deformar la puerta del coche."},"translation":{"en":"to dent; to emboss; (Burgos) to trample"}},"abollon":{"definition":"Abolladura o depresión en una superficie causada por un golpe o presión.","synonyms":["abolladura","bollo","bolladura","chopeadura"],"example":{"word":"abollón","text":"El mecánico reparó el abollón de la puerta."},"exampleSynonym":{"word":"abolladura","text":"El mecánico reparó la abolladura de la puerta."},"translation":{"en":"dent; ding"}},"abollonar":{"definition":"Repujar una superficie formando bollones o relieves redondeados; en Aragón, dicho de una planta, echar el bollón.","synonyms":["repujar","adornar con relieves"],"example":{"word":"abollonar","text":"El artesano empezó a abollonar la lámina de metal."},"exampleSynonym":{"word":"repujar","text":"El artesano empezó a repujar la lámina de metal."},"translation":{"en":"to emboss with rounded bosses; (Aragon) to bud"}},"abolsarse":{"definition":"Tomar forma de bolsa; dicho de la pintura de un techo o pared, ahuecarse y formar una o varias bolsas.","synonyms":["abombarse","ahuecarse","formar bolsas"],"example":{"word":"abolsarse","text":"Con la humedad, la pintura empezó a abolsarse en el techo."},"exampleSynonym":{"word":"ahuecarse","text":"Con la humedad, la pintura empezó a ahuecarse en el techo."},"translation":{"en":"to bulge into a bag-like shape; for paint to blister"}},"abomaso":{"definition":"(Zoología.) Cuarto estómago de los rumiantes, también llamado cuajar o cuajo; es la cámara glandular en la que se realiza la digestión química.","synonyms":["cuajar","cuajo"],"example":{"word":"abomaso","text":"En los rumiantes, el abomaso es la cámara glandular del estómago."},"exampleSynonym":{"word":"cuajar","text":"En los rumiantes, el cuajar es la cámara glandular del estómago."},"translation":{"en":"abomasum; rennet stomach"}},"abombado":{"definition":"(En Argentina, Costa Rica, Nicaragua, República Dominicana y Uruguay.) Tonto o falto de entendimiento; también, curvado o convexo, con forma esférica. Puede funcionar como adjetivo o sustantivo.","synonyms":["bobo","tonto","curvado","convexo","combado"],"example":{"word":"abombado","text":"En esa región, llaman abombado al personaje distraído y poco perspicaz."},"exampleSynonym":{"word":"bobo","text":"En esa región, llaman bobo al personaje distraído y poco perspicaz."},"translation":{"en":"(regional) foolish; convex; rounded"}}};for(const [id,data] of Object.entries(updates)){const row=rows.find(entry=>entry.id===id);if(!row)throw new Error('Missing dictionary entry: '+id);Object.assign(row,data);}})();




