;(()=>{const updates={"afantasmar":{"definition":"Verbo transitivo o pronominal: dar a alguien o algo aspecto o carácter fantasmal; dicho de alguien o algo, tomar ese aspecto.","synonyms":["dar aspecto fantasmal","fantasmagorizar"],"example":{"word":"Afantasmar","text":"La niebla llegó a afantasmar el paisaje y ocultó sus contornos."},"exampleSynonym":{"word":"dar aspecto fantasmal","text":"La niebla llegó a dar aspecto fantasmal al paisaje y ocultó sus contornos."},"translation":{"en":"to make ghostly; to take on a ghostly appearance"}},"afarallonado":{"definition":"Adjetivo: que tiene forma de farallón, es decir, de roca escarpada que sobresale; se aplica especialmente a puntas, cabos o bajos.","synonyms":["con forma de farallón","escarpado"],"example":{"word":"Afarallonado","text":"La costa afarallonada se alzaba sobre el mar."},"exampleSynonym":{"word":"con forma de farallón","text":"La costa con forma de farallón se alzaba sobre el mar."},"translation":{"en":"cliff-shaped; craggy"}},"afarolado":{"definition":"Adjetivo, tauromaquia: dicho de un lance o suerte, ejecutado pasando el capote por encima de la cabeza del torero, a modo de farol.","synonyms":["lance taurino con el capote por encima de la cabeza","de tipo farol"],"example":{"word":"Afarolado","text":"El torero terminó la serie con un lance afarolado."},"exampleSynonym":{"word":"de tipo farol","text":"El torero terminó la serie con un lance de tipo farol."},"translation":{"en":"performed with a cape-over-the-head flourish"}},"afascalar":{"definition":"Verbo transitivo, uso regional de Aragón y La Rioja: hacer fascales, es decir, hacinar o amontonar las gavillas de mies formando montones.","synonyms":["hacer fascales","hacinar gavillas","amontonar la mies"],"example":{"word":"Afascalar","text":"Tras la siega, los agricultores afascalaron las gavillas de mies."},"exampleSynonym":{"word":"hacinar gavillas","text":"Para hacinar gavillas, los agricultores las apilaron después de la siega."},"translation":{"en":"to stack sheaves; to make fascales"}},"afatar":{"definition":"Verbo transitivo, uso coloquial de Asturias y Galicia: aparejar una caballería, poniéndole los arreos necesarios.","synonyms":["aparejar una caballería","poner los arreos"],"example":{"word":"Afatar","text":"Antes de salir al camino, el mozo tuvo que afatar la mula."},"exampleSynonym":{"word":"aparejar una caballería","text":"Antes de salir al camino, el mozo tuvo que aparejar la mula."},"translation":{"en":"to harness or saddle a horse"}},"afeador":{"definition":"Adjetivo o sustantivo: que afea, desfigura o hace menos agradable a la vista; también, que desacredita o censura.","synonyms":["que desfigura","desfigurador","que desacredita"],"example":{"word":"Afeador","text":"El elemento afeador del paisaje fue retirado."},"exampleSynonym":{"word":"desfigurador","text":"El elemento desfigurador del paisaje fue retirado."},"translation":{"en":"disfiguring; detracting; discrediting"}},"afear":{"definition":"Verbo transitivo: hacer que alguien o algo resulte menos bello o agradable a la vista; también, censurar o reprochar una conducta.","synonyms":["desfigurar","estropear","censurar","reprochar"],"example":{"word":"Afear","text":"Afear la fachada con cables expuestos llevó al arquitecto a censurar la instalación."},"exampleSynonym":{"word":"desfigurar","text":"Desfigurar la fachada con cables expuestos llevó al arquitecto a censurar la instalación."},"translation":{"en":"to disfigure; to mar; to criticize; to reproach"}},"afeblecerse":{"definition":"Verbo pronominal, anticuado: adelgazar o volverse más débil, perdiendo corpulencia, fuerza o vigor.","synonyms":["adelgazarse","enflaquecerse","debilitarse"],"example":{"word":"Afeblecerse","text":"El enfermo empezó a afeblecerse durante la larga convalecencia."},"exampleSynonym":{"word":"debilitarse","text":"El enfermo empezó a debilitarse durante la larga convalecencia."},"translation":{"en":"to grow thin; to grow weak; to become feeble"}},"afeccionar":{"definition":"Verbo transitivo, anticuado: afectar o conmover el ánimo; causar una impresión emocional.","synonyms":["afectar","conmover","impresionar"],"example":{"word":"Afeccionar","text":"La noticia llegó a afeccionar profundamente a sus lectores."},"exampleSynonym":{"word":"conmover","text":"La noticia llegó a conmover profundamente a sus lectores."},"translation":{"en":"to affect; to move emotionally"}},"afeccionarse":{"definition":"Verbo pronominal: tomar afición, gusto o inclinación por alguien o algo.","synonyms":["aficionarse","encariñarse","tomar gusto"],"example":{"word":"Afeccionarse","text":"Con el tiempo llegó a afeccionarse a la lectura de historia."},"exampleSynonym":{"word":"aficionarse","text":"Con el tiempo llegó a aficionarse a la lectura de historia."},"translation":{"en":"to become fond of; to take a liking to"}}};for(const [id,data] of Object.entries(updates)){const row=window.DICCIONARIOS.es.find(entry=>entry.id===id);if(!row)throw new Error('Missing '+id);Object.assign(row,data);}})();

