;(()=>{const updates={"albero":{"definition":"Sustantivo masculino: tierra de color ocre usada en jardinería y en los ruedos taurinos; también, el ruedo de una plaza de toros, un terreno albarizo o un paño para secar platos. Como adjetivo desusado, significa albar.","synonyms":["arena","ruedo","redondel","paño de cocina"],"translation":{"en":"ochre soil; bullring arena; dish towel; (obsolete adjective) white"},"example":{"word":"albero","text":"Regaron el albero de la plaza antes de la corrida."},"exampleSynonym":{"word":"ruedo","text":"Regaron el ruedo de la plaza antes de la corrida."}},"alberque":{"definition":"Sustantivo masculino: alberca, depósito o estanque para almacenar agua.","synonyms":["alberca","depósito","estanque"],"translation":{"en":"reservoir; water tank; pool"},"example":{"word":"alberque","text":"El agua de lluvia llenó el alberque del huerto."},"exampleSynonym":{"word":"estanque","text":"El agua de lluvia llenó el estanque del huerto."}},"alberquero":{"definition":"Sustantivo masculino o femenino: persona que cuida de las albercas.","synonyms":["cuidador de albercas","mantenedor de piscinas"],"translation":{"en":"pool keeper; pool attendant"},"example":{"word":"alberquero","text":"El alberquero limpió la alberca al inicio de la temporada."},"exampleSynonym":{"word":"cuidador de albercas","text":"El cuidador de albercas limpió el estanque al inicio de la temporada."}},"albicante":{"definition":"Adjetivo: que albea, blanquea o muestra blancura.","synonyms":["blanqueante","blanquecino"],"translation":{"en":"whitening; growing white"},"example":{"word":"albicante","text":"La espuma albicante cubrió por un momento las rocas."},"exampleSynonym":{"word":"blanquecina","text":"La espuma blanquecina cubrió por un momento las rocas."}},"albihar":{"definition":"Sustantivo masculino: manzanilla loca, planta silvestre de flores semejantes a las de la manzanilla.","synonyms":["manzanilla loca"],"translation":{"en":"wild chamomile (common name)"},"example":{"word":"albihar","text":"El albihar crecía entre las hierbas del camino."},"exampleSynonym":{"word":"manzanilla loca","text":"La manzanilla loca crecía entre las hierbas del camino."}},"albilla":{"definition":"Sustantivo femenino: uva albilla, variedad de uva blanca.","synonyms":["uva albilla","albillo"],"translation":{"en":"albilla grape; white grape variety"},"example":{"word":"albilla","text":"La albilla se cosechó a finales del verano."},"exampleSynonym":{"word":"uva albilla","text":"La uva albilla se cosechó a finales del verano."}},"albillo":{"definition":"Sustantivo masculino o femenino: uva albilla; también, vino elaborado con esta variedad de uva.","synonyms":["albilla","uva albilla","vino albillo"],"translation":{"en":"albillo grape; wine made from it"},"example":{"word":"albillo","text":"Sirvieron un vino albillo fresco con la comida."},"exampleSynonym":{"word":"vino albillo","text":"Sirvieron un vino elaborado con uva albilla, fresco, con la comida."}},"albita":{"definition":"Sustantivo femenino, geología: feldespato compuesto principalmente por silicatos de aluminio y sodio, por lo general de color blanco.","synonyms":["feldespato sódico"],"translation":{"en":"albite; sodium feldspar"},"example":{"word":"albita","text":"La muestra de albita tenía un brillo vítreo y un tono blanco."},"exampleSynonym":{"word":"feldespato sódico","text":"La muestra de feldespato sódico tenía un brillo vítreo y un tono blanco."}},"albitana":{"definition":"Sustantivo femenino: cerca que protege las plantas en un jardín. En faluchos y embarcaciones menores, pieza estructural llamada contrarroda o contracodaste.","synonyms":["cerca protectora","contrarroda","contrabranque","contracodaste"],"translation":{"en":"protective garden fence; (nautical) stempost or sternpost"},"example":{"word":"albitana","text":"La albitana impedía que los animales pisaran las plantas jóvenes."},"exampleSynonym":{"word":"cerca protectora","text":"La cerca protectora impedía que los animales pisaran las plantas jóvenes."}},"alboaire":{"definition":"Sustantivo masculino: labor decorativa hecha con azulejos en capillas o bóvedas, especialmente en las esféricas. Como adjetivo poco usado, dicho de una bóveda o armadura, adornada con azulejos.","synonyms":["decoración de bóveda con azulejos"],"translation":{"en":"tile decoration on a chapel or vault; tiled (rare adjective)"},"example":{"word":"alboaire","text":"El alboaire de la capilla formaba un mosaico geométrico."},"exampleSynonym":{"word":"decoración de bóveda con azulejos","text":"La decoración de la bóveda con azulejos formaba un mosaico geométrico."}}};for(const [id,data] of Object.entries(updates)){const row=window.DICCIONARIOS.es.find(entry=>entry.id===id);if(!row)throw new Error('Missing '+id);Object.assign(row,data);}})();

