;(()=>{const updates={"alzacuello":{"definition":"m. Tira rígida o pieza blanca que se ajusta al cuello de la camisa y forma parte de la vestimenta clerical.","synonyms":["cuello clerical","cuello eclesiástico"],"example":{"word":"alzacuello","text":"El sacerdote se colocó el alzacuello antes de la ceremonia."},"exampleSynonym":{"word":"cuello clerical","text":"El sacerdote se colocó el cuello clerical antes de la ceremonia."},"translation":{"en":"clerical collar"}},"alzadera":{"definition":"f. ant. Especie de contrapeso o mecanismo que ayudaba a levantar o impulsar algo para saltar.","synonyms":["contrapeso para elevar","mecanismo de impulso"],"example":{"word":"alzadera","text":"El inventario antiguo describe una alzadera que ayudaba a elevar el mecanismo."},"exampleSynonym":{"word":"contrapeso para elevar","text":"El inventario antiguo describe un contrapeso para elevar el mecanismo."},"translation":{"en":"lifting counterweight or spring mechanism (obsolete)"}},"alzador":{"definition":"m. 1. Persona que alza o levanta algo. 2. Impr. Persona que ordena y reúne los pliegos impresos para su encuadernación.","synonyms":["ordenador de pliegos","operario de alzado"],"example":{"word":"alzador","text":"El alzador reunió los pliegos impresos en el orden necesario para encuadernarlos."},"exampleSynonym":{"word":"ordenador de pliegos","text":"El ordenador de pliegos reunió las hojas en el orden necesario para encuadernarlas."},"translation":{"en":"sheet collator; person who gathers printed sheets"}},"alzadora":{"definition":"f. Am. Máquina agrícola que recoge y carga la caña de azúcar cortada.","synonyms":["cargadora de caña","máquina recogedora de caña"],"example":{"word":"alzadora","text":"La alzadora recogió la caña cortada y la cargó en el remolque."},"exampleSynonym":{"word":"cargadora de caña","text":"La cargadora de caña recogió el cultivo cortado y lo cargó en el remolque."},"translation":{"en":"sugarcane loader; cane harvester"}},"alzadura":{"definition":"f. Acción y efecto de alzar o levantar.","synonyms":["alzamiento","elevación","levantamiento"],"example":{"word":"alzadura","text":"La alzadura de la compuerta permitió que el agua pasara al canal."},"exampleSynonym":{"word":"elevación","text":"La elevación de la compuerta permitió que el agua pasara al canal."},"translation":{"en":"lifting; raising"}},"alzapano":{"definition":"m. Pieza fijada a una pared o a una cortina que sirve para mantenerla recogida hacia un lado.","synonyms":["sujetacortinas","abrazadera de cortina","gancho de cortina"],"example":{"word":"alzapaño","text":"Sujetaron la cortina al alzapaño para dejar entrar la luz."},"exampleSynonym":{"word":"sujetacortinas","text":"Sujetaron la cortina al sujetacortinas para dejar entrar la luz."},"translation":{"en":"curtain holdback; curtain hook"}},"alzapie":{"definition":"m. 1. Pieza o apoyo donde se ponen los pies. 2. Lazo o trampa que sujeta por el pie a un animal.","synonyms":["reposapiés","estribo","trampa de lazo"],"example":{"word":"alzapié","text":"El viajero apoyó los pies en el alzapié de la silla."},"exampleSynonym":{"word":"reposapiés","text":"El viajero apoyó los pies en el reposapiés de la silla."},"translation":{"en":"footrest; foothold; foot snare"}},"alzapon":{"definition":"m. Portezuela que cubre la abertura delantera de algunos calzones y pantalones antiguos.","synonyms":["bragueta con portezuela","portezuela del pantalón"],"example":{"word":"alzapón","text":"El traje histórico llevaba un alzapón abotonado en la parte delantera."},"exampleSynonym":{"word":"portezuela del pantalón","text":"El traje histórico llevaba una portezuela del pantalón abotonada en la parte delantera."},"translation":{"en":"front flap of breeches (historical)"}},"alzaprima":{"definition":"f. Barra o palanca usada para levantar o hacer fuerza sobre un objeto.","synonyms":["palanca","barreta","barra de apalancar"],"example":{"word":"alzaprima","text":"Usaron una alzaprima para levantar la piedra y colocarla sobre la base."},"exampleSynonym":{"word":"palanca","text":"Usaron una palanca para levantar la piedra y colocarla sobre la base."},"translation":{"en":"lever; crowbar"}}};for(const [id,data] of Object.entries(updates)){const e=DICCIONARIOS.es.find(x=>x.id===id);if(!e)throw Error(id);Object.assign(e,data)}})();

;(()=>{const updates={"alzaprimar":{"definition":"tr. Levantar o hacer fuerza sobre algo con una alzaprima o palanca.","synonyms":["apalancar","levantar con una palanca","hacer palanca"],"example":{"word":"alzaprimar","text":"Tuvieron que alzaprimar la losa para colocarla sobre el muro."},"exampleSynonym":{"word":"apalancar","text":"Tuvieron que apalancar la losa para colocarla sobre el muro."},"translation":{"en":"to lever up; to pry up"}},"alzapuertas":{"definition":"m. desus. En una compañía teatral, persona que desempeña un papel secundario de criado o comparsa.","synonyms":["comparsa","papel secundario","criado de teatro"],"example":{"word":"alzapuertas","text":"El programa antiguo llamaba alzapuertas al actor que apenas intervenía en la comedia."},"exampleSynonym":{"word":"comparsa","text":"El programa antiguo llamaba comparsa al actor que apenas intervenía en la comedia."},"translation":{"en":"minor theatrical extra or servant role (obsolete)"}},"amacayo":{"definition":"m. Am. Planta bulbosa ornamental (Sprekelia formosissima), de flores rojas vistosas, también llamada flor de lis.","synonyms":["flor de lis","lirio azteca","Sprekelia formosissima"],"example":{"word":"amacayo","text":"El amacayo floreció con pétalos rojos después de las lluvias."},"exampleSynonym":{"word":"lirio azteca","text":"El lirio azteca floreció con pétalos rojos después de las lluvias."},"translation":{"en":"Aztec lily; Sprekelia formosissima"}},"amachetear":{"definition":"tr. Dar golpes o cortes con un machete.","synonyms":["machetear","golpear con un machete","cortar a machetazos"],"example":{"word":"amachetear","text":"El trabajador tuvo que amachetear la maleza que bloqueaba el sendero."},"exampleSynonym":{"word":"cortar a machetazos","text":"El trabajador tuvo que cortar a machetazos la maleza que bloqueaba el sendero."},"translation":{"en":"to hack or slash with a machete"}},"amacigado":{"definition":"adj. poco usado. Variante de almacigado: sembrado o dispuesto en un almácigo para que las plantas germinen y crezcan antes del trasplante.","synonyms":["almacigado","sembrado en almácigo"],"example":{"word":"amacigado","text":"El tomate amacigado se trasplantó cuando alcanzó el tamaño adecuado."},"exampleSynonym":{"word":"almacigado","text":"El tomate almacigado se trasplantó cuando alcanzó el tamaño adecuado."},"translation":{"en":"sown in a seedbed (rare variant)"}},"amacizar":{"definition":"tr. Hacer macizo o sólido algo, rellenándolo o consolidándolo.","synonyms":["macizar","rellenar","consolidar"],"example":{"word":"amacizar","text":"Añadieron piedra y mortero para amacizar la base del muro."},"exampleSynonym":{"word":"consolidar","text":"Añadieron piedra y mortero para consolidar la base del muro."},"translation":{"en":"to make solid; to fill in; to consolidate"}},"amacollar":{"definition":"intr. Dicho de una planta: Formar macolla, es decir, desarrollar varios tallos agrupados desde la base.","synonyms":["macollar","formar una macolla","ahijar"],"example":{"word":"amacollar","text":"El césped comenzó a amacollar después de las primeras lluvias."},"exampleSynonym":{"word":"formar una macolla","text":"El césped comenzó a formar una macolla después de las primeras lluvias."},"translation":{"en":"to form a clump or tuft; to tiller"}},"amadrigar":{"definition":"tr. y prnl. 1. Dar refugio o protección; acoger, a veces a quien no lo merece. 2. prnl. Dicho de un animal: Refugiarse en su madriguera; por extensión, retraerse y dejarse ver poco.","synonyms":["albergar","dar refugio","refugiarse en una madriguera","retraerse"],"example":{"word":"amadrigar","text":"La familia decidió amadrigar al animal herido hasta que pudiera volver a su madriguera."},"exampleSynonym":{"word":"dar refugio","text":"La familia decidió dar refugio al animal herido hasta que pudiera volver a su madriguera."},"translation":{"en":"to shelter; to take refuge in a burrow; to withdraw"}},"amadronado":{"definition":"adj. Parecido al madroño, especialmente por su aspecto, forma o color.","synonyms":["semejante al madroño","con aspecto de madroño"],"example":{"word":"amadroñado","text":"El fruto amadronado tenía una superficie rugosa y rojiza."},"exampleSynonym":{"word":"semejante al madroño","text":"El fruto semejante al madroño tenía una superficie rugosa y rojiza."},"translation":{"en":"resembling the strawberry tree or its fruit"}},};for(const [id,data] of Object.entries(updates)){const e=DICCIONARIOS.es.find(x=>x.id===id);if(!e)throw Error(id);Object.assign(e,data)}})();

;(()=>{const updates={"amaestradura":{"definition":"f. desus. Artificio o maña empleado para disimular, engañar o conseguir algo con habilidad.","synonyms":["artificio","maña","engaño disimulado"],"example":{"word":"amaestradura","text":"El memorial antiguo denunciaba la amaestradura con que el mercader ocultaba sus trampas."},"exampleSynonym":{"word":"artificio","text":"El memorial antiguo denunciaba el artificio con que el mercader ocultaba sus trampas."},"translation":{"en":"artifice; deceptive stratagem (obsolete)"}},"amagar":{"definition":"tr. 1. Hacer ademán de golpear, atacar o ejecutar una acción, sin llegar necesariamente a realizarla. 2. Mostrar señales de que algo está a punto de ocurrir. 3. intr. rur. Amenazar.","synonyms":["hacer ademán de","fintar","amenazar"],"example":{"word":"amagar","text":"El boxeador amagó un golpe con la izquierda y atacó con la derecha."},"exampleSynonym":{"word":"fintar","text":"El boxeador fintó un golpe con la izquierda y atacó con la derecha."},"translation":{"en":"to feint; to threaten; to show signs of"}},"amago":{"definition":"m. 1. Acción de amagar; ademán o intento de ataque que no llega a consumarse. 2. Señal o indicio de que algo va a ocurrir. 3. Variante de amague en algunas regiones.","synonyms":["finta","ademán de ataque","conato","indicio"],"example":{"word":"amago","text":"El delantero hizo un amago hacia la izquierda y pasó el balón a un compañero."},"exampleSynonym":{"word":"finta","text":"El delantero hizo una finta hacia la izquierda y pasó el balón a un compañero."},"translation":{"en":"feint; attempt; sign or threat of something"}},"amainador":{"definition":"m. Persona o dispositivo que amaina, reduce o afloja algo, especialmente una vela o cabo de una embarcación.","synonyms":["persona que reduce una vela","dispositivo para aflojar"],"example":{"word":"amainador","text":"El amainador aflojó la vela cuando el viento empezó a arreciar."},"exampleSynonym":{"word":"persona que reduce una vela","text":"La persona que reduce una vela la aflojó cuando el viento empezó a arreciar."},"translation":{"en":"person or device that eases or lowers a sail"}},"amaitinar":{"definition":"tr. rur. Observar o mirar con atención; acechar o espiar.","synonyms":["atisbar","acechar","espiar"],"example":{"word":"amaitinar","text":"El pastor se detuvo a amaitinar el monte antes de cruzar el paso."},"exampleSynonym":{"word":"atisbar","text":"El pastor se detuvo a atisbar el monte antes de cruzar el paso."},"translation":{"en":"to watch carefully; to spy or lie in wait (rural)"}},"amajadar":{"definition":"tr. Preparar o señalar un terreno como majada o redil para que el ganado pase allí la noche y lo abone.","synonyms":["hacer una majada","establecer un redil","apacentar de noche"],"example":{"word":"amajadar","text":"El pastor decidió amajadar el prado para que el rebaño descansara allí."},"exampleSynonym":{"word":"establecer un redil","text":"El pastor decidió establecer un redil en el prado para que el rebaño descansara allí."},"translation":{"en":"to make a sheepfold; to pen livestock overnight"}},"amajanar":{"definition":"tr. rurales. Marcar los límites de una finca o campo colocando majanos o montones de piedras.","synonyms":["marcar con majanos","señalar los lindes","amojonar"],"example":{"word":"amajanar","text":"Los vecinos acordaron amajanar el lindero para dejar claros los límites de cada campo."},"exampleSynonym":{"word":"amojonar","text":"Los vecinos acordaron amojonar el lindero para dejar claros los límites de cada campo."},"translation":{"en":"to mark field boundaries with stone heaps"}},"amalaya":{"definition":"interj. Am. Expresa deseo, queja o lamento; equivale a ojalá o a una imprecación, según el contexto.","synonyms":["ojalá","quiera Dios","ojalá que"],"example":{"word":"amalaya","text":"¡Amalaya que mañana deje de llover!, dijo el campesino."},"exampleSynonym":{"word":"ojalá","text":"¡Ojalá que mañana deje de llover!, dijo el campesino."},"translation":{"en":"if only; would that; alas (American regional interjection)"}},"amalear":{"definition":"tr. y prnl. desus. Malear o echar a perder; corromper o volverse malo.","synonyms":["malear","corromper","echar a perder"],"example":{"word":"amalear","text":"La mala compañía podía amalear al muchacho, según advertía el refrán."},"exampleSynonym":{"word":"malear","text":"La mala compañía podía malear al muchacho, según advertía el refrán."},"translation":{"en":"to corrupt; to spoil (obsolete)"}}};for(const [id,data] of Object.entries(updates)){const e=DICCIONARIOS.es.find(x=>x.id===id);if(!e)throw Error(id);Object.assign(e,data)}})();

