;(()=>{const u={"apologo":{"definition":"Relato breve de ficción, a menudo con intención didáctica o moral; también, adjetivo poco usado equivalente a apológico.","synonyms":["fábula","parábola","cuento didáctico","alegoría"],"example":{"word":"apólogo","text":"El apólogo cuenta la historia de dos animales y termina con una enseñanza."},"exampleSynonym":{"word":"fábula","text":"La fábula cuenta la historia de dos animales y termina con una enseñanza."},"translation":{"en":"apologue; fable; moral tale"}},"apoltronarse":{"definition":"Dicho de una persona, especialmente sedentaria: hacerse perezosa o poco activa; también, sentarse o recostarse con comodidad y holgura.","synonyms":["holgazanear","vegetar","repantigarse","arrellanarse"],"example":{"word":"apoltronarse","text":"Después de jubilarse, no quiso apoltronarse y siguió caminando a diario."},"exampleSynonym":{"word":"holgazanear","text":"Después de jubilarse, no quiso holgazanear y siguió caminando a diario."},"translation":{"en":"to become sedentary or lazy; to settle back comfortably"}},"aponzonar":{"definition":"Forma anticuada de aponzoñar: envenenar.","synonyms":["envenenar","emponzoñar"],"example":{"word":"aponzoñar","text":"La crónica antigua afirma que intentaron aponzoñar el agua del pozo."},"exampleSynonym":{"word":"envenenar","text":"La crónica antigua afirma que intentaron envenenar el agua del pozo."},"translation":{"en":"to poison (obsolete)"}},"apoquinar":{"definition":"Coloquial: pagar o hacerse cargo, por lo general de mala gana, del gasto o de la parte que a uno le corresponde.","synonyms":["pagar","abonar","satisfacer","cargar con el gasto"],"example":{"word":"apoquinar","text":"Al final todos tuvieron que apoquinar su parte de la cuenta."},"exampleSynonym":{"word":"pagar","text":"Al final todos tuvieron que pagar su parte de la cuenta."},"translation":{"en":"to pay up; to cough up one’s share (colloquial)"}},"aporcador":{"definition":"Que aporca; también, persona o instrumento que amontona tierra alrededor de las plantas.","synonyms":["aporcador de tierra","instrumento para aporcar"],"example":{"word":"aporcador","text":"El aporcador cubrió con tierra la base de las plantas."},"exampleSynonym":{"word":"instrumento para aporcar","text":"El instrumento para aporcar cubrió con tierra la base de las plantas."},"translation":{"en":"earthing-up tool; one that hills soil around plants"}},"aporcadura":{"definition":"Acción y efecto de aporcar: amontonar tierra alrededor del tallo de una planta.","synonyms":["aporque","acogombradura","aporcado"],"example":{"word":"aporcadura","text":"La aporcadura protegió los tallos tiernos del viento."},"exampleSynonym":{"word":"aporque","text":"El aporque protegió los tallos tiernos del viento."},"translation":{"en":"earthing up; hilling soil around a plant"}},"aporcar":{"definition":"Amontonar tierra alrededor del tallo de ciertas plantas, como el apio o la escarola, para cubrirlas o favorecer su crecimiento.","synonyms":["acogombrar","arrimar tierra","hacer un aporque"],"example":{"word":"aporcar","text":"El agricultor empezó a aporcar el apio para blanquear sus tallos."},"exampleSynonym":{"word":"acogombrar","text":"El agricultor empezó a acogombrar el apio para blanquear sus tallos."},"translation":{"en":"to earth up; to hill soil around a plant"}},"aporetico":{"definition":"En filosofía, perteneciente o relativo a una aporía: una dificultad lógica o filosófica aparentemente insoluble.","synonyms":["relativo a una aporía","aporístico"],"example":{"word":"aporético","text":"El argumento aporético expone una dificultad sin ofrecer una solución concluyente."},"exampleSynonym":{"word":"relativo a una aporía","text":"El argumento relativo a una aporía expone una dificultad sin ofrecer una solución concluyente."},"translation":{"en":"aporetic; relating to an aporia or philosophical impasse"}},"aporque":{"definition":"Acción y efecto de aporcar, es decir, de amontonar tierra alrededor del tallo de una planta.","synonyms":["aporcadura","acogombradura"],"example":{"word":"aporque","text":"El aporque de las patatas se hizo antes de que crecieran demasiado."},"exampleSynonym":{"word":"aporcadura","text":"La aporcadura de las patatas se hizo antes de que crecieran demasiado."},"translation":{"en":"earthing up; hilling"}},"aporreador":{"definition":"Que aporrea; también, persona que golpea repetidamente o instrumento empleado para golpear o machacar.","synonyms":["golpeador","mazador","instrumento para aporrear"],"example":{"word":"aporreador","text":"El aporreador de cuero machacó la fibra hasta volverla flexible."},"exampleSynonym":{"word":"mazador","text":"El mazador de cuero machacó la fibra hasta volverla flexible."},"translation":{"en":"one who beats or pounds; pounding tool"}}};for(const[id,v]of Object.entries(u)){const e=DICCIONARIOS.es.find(x=>x.id===id);if(!e)throw Error('missing es/'+id);Object.assign(e,v)}})();

;(()=>{const u={"aporrear":{"definition":"Dar golpes repetidos con una porra o con cualquier otro objeto; también, machacar, importunar o molestar. En Venezuela puede significar golpear accidentalmente o atropellar, y, poco usado, sacudir o ahuyentar moscas.","synonyms":["golpear repetidamente","apalear","machacar","fastidiar","molestar"],"example":{"word":"aporrear","text":"Dejó de aporrear la puerta cuando oyó pasos en el pasillo."},"exampleSynonym":{"word":"golpear repetidamente","text":"Dejó de golpear repetidamente la puerta cuando oyó pasos en el pasillo."},"translation":{"en":"to beat repeatedly; to pound; to pester; (Venezuela) to hit accidentally or run over"}},"aporreo":{"definition":"Acción y efecto de aporrear o aporrearse, especialmente una serie de golpes fuertes.","synonyms":["apalizamiento","apaleamiento","aporreamiento","tunda"],"example":{"word":"aporreo","text":"El aporreo de la puerta despertó a toda la casa."},"exampleSynonym":{"word":"aporreamiento","text":"El aporreamiento de la puerta despertó a toda la casa."},"translation":{"en":"beating; pounding; thrashing"}},"aposiopesis":{"definition":"En retórica, interrupción intencional de una frase antes de completarla, dejando implícita la continuación.","synonyms":["reticencia","interrupción retórica","enunciado truncado"],"example":{"word":"aposiopesis","text":"Al decir «Si vuelves a hacerlo…», el personaje emplea una aposiopesis."},"exampleSynonym":{"word":"reticencia","text":"Al decir «Si vuelves a hacerlo…», el personaje emplea una reticencia."},"translation":{"en":"aposiopesis; rhetorical breaking-off; aposiopesis"}},"apostata":{"definition":"Persona que apostata, es decir, que abandona públicamente una fe, religión, doctrina o principios que antes profesaba.","synonyms":["renegado","desertor","tránsfuga","hereje (según el contexto)"],"example":{"word":"apóstata","text":"El apóstata renunció públicamente a la doctrina que había seguido."},"exampleSynonym":{"word":"renegado","text":"El renegado renunció públicamente a la doctrina que había seguido."},"translation":{"en":"apostate; renegade; defector"}},"apostatar":{"definition":"Abandonar públicamente una religión, una fe, una orden, una doctrina o los principios que antes se profesaban.","synonyms":["renegar","abjurar","desertar"],"example":{"word":"apostatar","text":"Decidió apostatar de la orden después de años de reflexión."},"exampleSynonym":{"word":"renegar","text":"Decidió renegar de la orden después de años de reflexión."},"translation":{"en":"to apostatize; to renounce or abandon a faith or doctrine"}},"apostillarse":{"definition":"Llenarse de postillas o costras pequeñas.","synonyms":["cubrirse de postillas","formar costras"],"example":{"word":"apostillarse","text":"La piel puede apostillarse durante la recuperación de la erupción."},"exampleSynonym":{"word":"cubrirse de postillas","text":"La piel puede cubrirse de postillas durante la recuperación de la erupción."},"translation":{"en":"to become covered with scabs or crusts"}},"apostolico":{"definition":"Perteneciente o relativo a los apóstoles o al papa; por extensión, propio de un apóstol o conforme a su doctrina.","synonyms":["relativo a los apóstoles","papal","pontificio"],"example":{"word":"apostólico","text":"El nuncio presentó sus credenciales ante la autoridad apostólica."},"exampleSynonym":{"word":"papal","text":"El nuncio presentó sus credenciales ante la autoridad papal."},"translation":{"en":"apostolic; papal; pontifical"}},"apostoligo":{"definition":"Voz anticuada: papa.","synonyms":["papa","pontífice romano"],"example":{"word":"apostóligo","text":"En el manuscrito antiguo, apostóligo designa al papa."},"exampleSynonym":{"word":"papa","text":"En el manuscrito antiguo, papa es el sentido de apostóligo."},"translation":{"en":"pope (obsolete form)"}},"apostolo":{"definition":"Forma antigua o dialectal de apóstol: cada uno de los discípulos de Jesucristo y, en general, quien difunde una doctrina.","synonyms":["apóstol","discípulo"],"example":{"word":"apóstolo","text":"El texto medieval llama apóstolo al discípulo que predica la nueva doctrina."},"exampleSynonym":{"word":"apóstol","text":"El texto medieval llama apóstol al discípulo que predica la nueva doctrina."},"translation":{"en":"apostle (archaic or dialectal form)"}}};for(const[id,v]of Object.entries(u)){const e=DICCIONARIOS.es.find(x=>x.id===id);if(!e)throw Error('missing es/'+id);Object.assign(e,v)}})();
