set('cacharreria',{definition:'Tienda de cacharros o de loza ordinaria.',synonyms:['tienda de cacharros','tienda de loza'],example:{word:'cacharrería',text:'Compró una olla de barro en la cacharrería del barrio.'},exampleSynonym:{word:'tienda de cacharros',text:'Compró una olla de barro en la tienda de cacharros del barrio.'},translation:{en:'shop selling pots and ordinary earthenware'}});
set('cachativa',{definition:'En Chile, coloquialmente, capacidad de intuir algo con agudeza y rapidez.',synonyms:['intuición aguda','perspicacia'],example:{word:'cachativa',text:'Tuvo la cachativa de descubrir enseguida el engaño.'},exampleSynonym:{word:'perspicacia',text:'Tuvo la perspicacia de descubrir enseguida el engaño.'},translation:{en:'quick intuition; insight'}});
set('cachava',{definition:'Cayado o bastón; también, antiguo juego infantil que consistía en introducir con un palo una pelota en hoyos abiertos en el suelo.',synonyms:['cayado','bastón','juego de pelota y hoyos'],example:{word:'cachava',text:'El pastor avanzaba apoyado en su cachava.'},exampleSynonym:{word:'cayado',text:'El pastor avanzaba apoyado en su cayado.'},translation:{en:'crook; old ball-and-hole game'}});
set('cachavazo',{definition:'Golpe dado con una cachava.',synonyms:['golpe con una cachava','bastonazo'],example:{word:'cachavazo',text:'El hombre recibió un cachavazo en el hombro.'},exampleSynonym:{word:'bastonazo',text:'El hombre recibió un bastonazo en el hombro.'},translation:{en:'blow with a crook'}});
